/**
 * Tokens whose CSS is a `color-mix()` while the literal above is a flattened hex.
 *
 * Same colour, never the same string — the CSS keeps the alias chain to `--sys-*`
 * alive, the literal is what a table prints. A textual comparison must skip these
 * rather than call them drift.
 */
export const TOKEN_VALUES_ALPHA: readonly string[] = [
  "--btn-primary-shadow",
  "--btn-secondary-shadow",
  "--btn-outline-shadow",
  "--btn-special-shadow",
  "--checkbox-focus-ring-success",
  "--checkbox-focus-ring-primary",
  "--dropdown-ring-active",
  "--radio-ring-gray",
  "--radio-ring-green",
  "--text-field-ring-active",
] as const;

export type TokenName = keyof typeof TOKEN_VALUES;

/** The CSS reference a component renders with, e.g. `var(--btn-radius)`. */
export const cssVar = (name: TokenName, fallback?: string): string =>
  fallback ? `var(${name}, ${fallback})` : `var(${name})`;

/** The resolved literal behind a token — for docs, tables and assertions. */
export const tokenValue = (name: TokenName): string => TOKEN_VALUES[name];
